    if(j===4){var p5=pick([0.03,0.05,0.1],k%3),s5=pick([0.7,0.9],j%2),fp5=pick([0.01,0.05],(k+1)%2),ans5=bayes(p5,s5,fp5);return n("", "Ошибка встречается у "+pct(p5*100)+" операций. Детектор ловит "+pct(s5*100)+" ошибок и тревожится на "+pct(fp5*100)+" нормальных операций. Алерт сработал. Вероятность реальной ошибки?",ans5,"%",["Составь 1 000 или 10 000 операций.","Сравни настоящие и ложные алерты; получится "+pct(ans5)+"."],"Высокая чувствительность не отменяет ложноположительные сигналы.",1);}
