    if(j===0){var ev=p*win-cost;return n("", "Проект стоит "+cost+"k. При успехе он даёт "+win+"k эффекта, при провале — 0. Вероятность успеха "+pct(p*100)+". Каков чистый EV?",ev,"k",["Ожидаемый эффект: "+f(p*win,1)+"k.","Минус стоимость "+cost+"k = "+f(ev,1)+"k."],"Стоимость входа вычитается из ожидаемого эффекта.",0.3);}
    if(j===1){var threshold=cost/win*100;return n("", "Проект стоит "+cost+"k и при успехе даёт "+win+"k. При какой вероятности успеха EV равен нулю?",threshold,"%",["p × "+win+" = "+cost+".","p = "+cost+" / "+win+" = "+pct(threshold)+"."],"Порог — затраты, делённые на выигрыш, а не наоборот.",0.3);}
