    if(j===3){var good=pick([100,150,200,300],k%4),bad=pick([-20,-40,-60,-100],j%4),p2=pick([0.4,0.6,0.7,0.8],(k+1)%4),ev3=p2*good+(1-p2)*bad;return n("", "При успехе результат +"+good+"k, при провале "+bad+"k, вероятность успеха "+pct(p2*100)+". Каков EV?",ev3,"k",["Вклад успеха: "+f(p2*good,1)+"k.","Вклад провала: "+f((1-p2)*bad,1)+"k.","Сумма = "+f(ev3,1)+"k."],"Убыток при провале сохраняет отрицательный знак.",0.3);}
